def get(cmd_args):
    r=subprocess.run(["./executable"]+cmd_args, capture_output=True, text=True, timeout=30)
    return r.stdout.splitlines()
samples=[]
for unit,dur in [("millisecond","0.001"),("millisecond","0.1"),("millisecond","1.01"),("microsecond","0.001"),("microsecond","0.01"),("second","0.1"),("second","1.01")]:
