#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
int main(){
 FILE*f=fopen("/tmp/counter","r"); int c=0; if(f){fscanf(f,"%d",&c); fclose(f);} 
 f=fopen("/tmp/counter","w"); fprintf(f,"%d",c+1); fclose(f);
 FILE*t=fopen("/tmp/times.txt","r"); char buf[4096]={0}; if(t){fgets(buf,sizeof buf,t); fclose(t);} 
 // token by comma
 int idx=0; char *save=NULL; char *tok=strtok_r(buf,",",&save); long ms=0;
 while(tok){ if(idx==c) ms=atol(tok); idx++; tok=strtok_r(NULL,",",&save); }
 if(c>=idx) ms=0;
 struct timespec ts={ms/1000,(ms%1000)*1000000L}; nanosleep(&ts,NULL); return 0;
}
EOF
