_add(Spec("parameter_step_size", "D", "parameter-step-size", "--parameter-step-size <DELTA>",
          requires="parameter_scan"))
_add(Spec("parameter_list", "L", "parameter-list", "--parameter-list <VAR> <VALUES>",
          kind="append", num=2, conflicts=["parameter_scan"], allow_hyphen=True))
_add(Spec("shell", "S", "shell", "--shell <SHELL>"))
_add(Spec("no_shell", "N", None, "-N", kind="flag", conflicts=["shell"]))
# fix shell conflicts (needs reverse ref)
_spec_by_long["shell"].conflicts = ["no_shell"]
_add(Spec("ignore_failure", "i", "ignore-failure", "--ignore-failure[=<MODE>]", kind="optflag"))
_add(Spec("style", None, "style", "--style <TYPE>",
          values=["auto", "basic", "full", "nocolor", "color", "none"], conflicts=["show_output"]))
_add(Spec("sort", None, "sort", "--sort <METHOD>", values=["auto", "command", "mean-time"]))
_add(Spec("time_unit", "u", "time-unit", "--time-unit <UNIT>",
          values=["microsecond", "millisecond", "second"]))
_add(Spec("export_asciidoc", None, "export-asciidoc", "--export-asciidoc <FILE>"))
