_add(Spec("version", "V", "version", "--version", kind="flag"))

SPEC_BY_KEY = {s.key: s for s in SPECS}


def _jw(a, b):
    if a == b:
        return 1.0
    la, lb = len(a), len(b)
    if la == 0 or lb == 0:
        return 0.0
    match_dist = max(la, lb) // 2 - 1
    if match_dist < 0:
        match_dist = 0
    a_matches = [False] * la
    b_matches = [False] * lb
    matches = 0
    for i in range(la):
        start = max(0, i - match_dist)
        end = min(i + match_dist + 1, lb)
        for j in range(start, end):
            if not b_matches[j] and a[i] == b[j]:
                a_matches[i] = True
                b_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    t = 0
    k = 0
    for i in range(la):
        if a_matches[i]:
            while not b_matches[k]:
                k += 1
            if a[i] != b[k]:
                t += 1
            k += 1
    t //= 2
    jaro = (matches / la + matches / lb + (matches - t) / matches) / 3.0
    prefix = 0
    for i in range(min(4, la, lb)):
        if a[i] == b[i]:
            prefix += 1
        else:
            break
    if jaro > 0.7:
        jaro += prefix * 0.1 * (1 - jaro)
    return jaro


def suggest_long(name):
    target = "--" + name
    candidates = sorted([s.long for s in SPECS if s.long])
    best = None
    best_score = 0.0
    for cand in candidates:
        score = _jw(target, "--" + cand)
        if score > best_score:
            best_score = score
            best = cand
    if best is not None and best_score > 0.8:
        return best
    return None


class ClapExit(Exception):
    def __init__(self, code):
        self.code = code


class Parser:
    def __init__(self, argv):
        self.argv = argv
        self.bin = _bin_name()
        self.values = {}        # key -> value or list
        self.present = []       # keys in first appearance order
        self.present_set = set()
        self.commands = []
        self.duplicates = []    # keys in order of duplicate occurrence
        self._dup_seen = set()

    # -- usage helpers
    def full_usage(self):
        return f"Usage: {self.bin} [OPTIONS] <command>..."

    def smart_usage(self, keys, extra_missing=None):
        parts = []
        if extra_missing:
            for k in extra_missing:
                parts.append(SPEC_BY_KEY[k].display)
        for k in keys:
            parts.append(SPEC_BY_KEY[k].display)
        if parts:
            return f"Usage: {self.bin} " + " ".join(parts) + " <command>..."
        return f"Usage: {self.bin} <command>..."

    def error_exit(self, text):
        err_write(text)
        raise ClapExit(2)

    def err_unexpected(self, shown, present_before, is_long, raw_name=None):
        if is_long:
            cand = suggest_long(raw_name)
            if cand is not None:
                cand_spec = _spec_by_long[cand]
                text = (f"error: unexpected argument '--{raw_name}' found\n\n"
                        f"  tip: a similar argument exists: '--{cand}'\n\n"
                        f"Usage: {self.bin} {cand_spec.display} <command>...\n\n"
                        f"For more information, try '--help'.\n")
                self.error_exit(text)
            tip = f"  tip: to pass '--{raw_name}' as a value, use '-- --{raw_name}'\n\n"
            first = f"error: unexpected argument '--{raw_name}' found\n\n"
        else:
            tip = f"  tip: to pass '{shown}' as a value, use '-- {shown}'\n\n"
            first = f"error: unexpected argument '{shown}' found\n\n"
        if present_before:
            usage = self.smart_usage(present_before)
        else:
            usage = self.full_usage()
        self.error_exit(first + tip + usage + "\n\nFor more information, try '--help'.\n")

    def err_missing_value(self, spec):
        text = f"error: a value is required for '{spec.display}' but none was supplied\n"
        if spec.values:
            text += "  [possible values: " + ", ".join(spec.values) + "]\n"
        text += "\nFor more information, try '--help'.\n"
        self.error_exit(text)

    def err_invalid_value(self, spec, val):
        text = (f"error: invalid value '{val}' for '{spec.display}'\n"
                f"  [possible values: " + ", ".join(spec.values) + "]\n\n"
                f"For more information, try '--help'.\n")
        self.error_exit(text)

    def err_num_values(self, spec, count):
        verb = "was" if count == 1 else "were"
        text = (f"error: {spec.num} values required for '{spec.display}' but {count} {verb} provided\n\n"
                f"{self.full_usage()}\n\nFor more information, try '--help'.\n")
        self.error_exit(text)

    def err_unexpected_value(self, spec, val):
        text = (f"error: unexpected value '{val}' for '{spec.display}' found; no more were expected\n\n"
                f"Usage: {self.bin} {spec.display} <command>...\n\n"
                f"For more information, try '--help'.\n")
        self.error_exit(text)

    # -- recording
    def note_present(self, spec):
        if spec.key not in self.present_set:
            self.present_set.add(spec.key)
            self.present.append(spec.key)

    def record(self, spec, vals):
        """vals: list of strings (for optflag: [] or [v])"""
        is_dup = spec.key in self.present_set
        self.note_present(spec)
        if spec.kind == "append":
            cur = self.values.setdefault(spec.key, [])
            if spec.num == 1:
                cur.append(vals[0])
            else:
                cur.append(list(vals))
            return
        if spec.kind == "flag":
            if is_dup and spec.key not in self._dup_seen:
                self._dup_seen.add(spec.key)
                self.duplicates.append(spec.key)
            self.values[spec.key] = True
            return
        if spec.kind == "optflag":
            if is_dup and spec.key not in self._dup_seen:
                self._dup_seen.add(spec.key)
                self.duplicates.append(spec.key)
            elif not is_dup:
                self.values[spec.key] = vals[0] if vals else None
            return
        # set
        if is_dup:
            if spec.key == "shell":
                self.values[spec.key] = vals[0] if vals else None
                return
            if spec.key not in self._dup_seen:
                self._dup_seen.add(spec.key)
                self.duplicates.append(spec.key)
            return  # keep first
        if spec.num == 1:
            self.values[spec.key] = vals[0]
        else:
            self.values[spec.key] = list(vals)

    def check_value(self, spec, val, is_dup):
        if spec.values is not None:
            if val == "":
                self.err_missing_value(spec)
            if is_dup:
                return
            if val not in spec.values:
                self.err_invalid_value(spec, val)

    # -- token classification
    def classify_option_token(self, tok):
        """Return ('long', spec or None, rawname) / ('short', char, spec or None) / None"""
        if tok.startswith("--") and len(tok) > 2:
            raw = tok[2:].split("=", 1)[0]
            return ("long", _spec_by_long.get(raw), raw)
        if tok.startswith("-") and len(tok) > 1 and tok != "--":
            ch = tok[1]
            return ("short", ch, _spec_by_short.get(ch))
        return None

    def is_known_option_token(self, tok):
        c = self.classify_option_token(tok)
        if c is None:
            return False
        if c[0] == "long":
            return c[1] is not None
        return c[2] is not None

    # gather values for a spec, starting with optional first value already given.
    # idx points to next unconsumed argv element. Returns new idx.
    def gather(self, spec, first_vals, i, present_before):
        vals = list(first_vals)
        # Validate already-given values for enum (single only)
        if spec.num == 1 and vals:
            self.check_value(spec, vals[0], spec.key in self.present_set and spec.key != "shell" and self.values.get(spec.key) is not None)
            # record happens in caller
            return i
        while len(vals) < spec.num:
            if i >= len(self.argv):
                if not vals:
                    self.err_missing_value(spec)
                else:
                    self.err_num_values(spec, len(vals))
            tok = self.argv[i]
            if tok == "--":
                if not vals:
                    self.err_missing_value(spec)
                else:
                    self.err_num_values(spec, len(vals))
            if spec.allow_hyphen:
                if self.is_known_option_token(tok):
                    self.err_num_values(spec, len(vals))
                vals.append(tok)
                i += 1
                continue
            # non-hyphen
            if tok.startswith("-") and tok != "-":
                cls = self.classify_option_token(tok)
                if cls[0] == "long":
                    if cls[1] is None:
                        self.err_unexpected("--" + cls[2], present_before, True, cls[2])
                    else:
                        if not vals:
                            self.err_missing_value(spec)
                        else:
                            self.err_num_values(spec, len(vals))
                else:
                    if cls[2] is None:
                        self.err_unexpected("-" + cls[1], present_before, False)
                    else:
                        if not vals:
                            self.err_missing_value(spec)
                        else:
                            self.err_num_values(spec, len(vals))
            vals.append(tok)
            i += 1
        return i

    def parse(self):
        argv = self.argv
        i = 0
        only_positional = False
        while i < len(argv):
            tok = argv[i]
            if only_positional:
                self.add_command(tok)
                i += 1
                continue
            if tok == "--":
                only_positional = True
                i += 1
                continue
            if tok.startswith("--") and len(tok) > 2:
                present_before = list(self.present)
                body = tok[2:]
                if "=" in body:
                    name, eq_val = body.split("=", 1)
                    has_eq = True
                else:
                    name, eq_val, has_eq = body, None, False
                spec = _spec_by_long.get(name)
                if spec is None:
                    self.err_unexpected("--" + name, present_before, True, name)
                if spec.key in ("help", "version"):
                    if has_eq:
                        self.err_unexpected_value(spec, eq_val)
                    self.do_help_version(spec.key)
                if spec.kind == "flag":
                    if has_eq:
                        self.err_unexpected_value(spec, eq_val)
                    self.record(spec, [])
                    i += 1
                    continue
                if spec.kind == "optflag":
                    if has_eq:
                        self.record(spec, [eq_val])
                    else:
                        self.record(spec, [])
                    i += 1
                    continue
                # option with values
                was_present = spec.key in self.present_set
                if has_eq:
                    first = [eq_val]
                    if spec.num == 1:
                        self.check_value(spec, eq_val, was_present)
                        self.record(spec, first)
                        i += 1
                    else:
                        # record consumes check later; gather remaining
                        self.record(spec, []) if False else None
                        # We need record with full values; gather rest first
                        # Undo: gather remaining values
                        idx = self.gather(spec, first, i + 1, present_before)
                        # gather already validated nothing for num>1; now record
                        # Reconstruct vals: gather didn't return them; redo logic below
                        # (handled in gather_multi)
                        i = idx
                    continue
                else:
                    if spec.num == 1:
                        idx = [None]  # placeholder
                        vals, idx2 = self.gather_single(spec, i + 1, present_before)
                        self.check_value(spec, vals[0], was_present)
                        self.record(spec, vals)
                        i = idx2
                    else:
                        vals, idx2 = self.gather_multi(spec, [], i + 1, present_before)
                        self.record(spec, vals)
                        i = idx2
                    continue
            elif tok.startswith("-") and len(tok) > 1:
                # short cluster
                present_before_token = list(self.present)
                chars = tok[1:]
                j = 0
                consumed_next = None
                while j < len(chars):
                    ch = chars[j]
                    spec = _spec_by_short.get(ch)
                    if spec is None:
                        self.err_unexpected("-" + ch, list(self.present), False)
                    if spec.key in ("help", "version"):
                        self.do_help_version(spec.key)
                    if spec.kind == "flag":
                        self.record(spec, [])
                        j += 1
                        continue
                    if spec.kind == "optflag":
                        rest = chars[j + 1:]
                        if rest.startswith("="):
                            self.record(spec, [rest[1:]])
                            j = len(chars)
                        elif rest == "":
                            self.record(spec, [])
                            j = len(chars)
                        else:
                            self.record(spec, [])
                            j += 1
                        continue
                    # option with values
                    was_present = spec.key in self.present_set
                    rest = chars[j + 1:]
                    if rest != "":
                        first_val = rest[1:] if rest.startswith("=") else rest
                        if spec.num == 1:
                            self.check_value(spec, first_val, was_present)
                            self.record(spec, [first_val])
                        else:
                            vals, idx2 = self.gather_multi(spec, [first_val], i + 1, list(self.present))
                            self.record(spec, vals)
                            consumed_next = idx2
                        j = len(chars)
                    else:
                        if spec.num == 1:
                            vals, idx2 = self.gather_single(spec, i + 1, present_before_token)
                            self.check_value(spec, vals[0], was_present)
                            self.record(spec, vals)
                            consumed_next = idx2
                        else:
                            vals, idx2 = self.gather_multi(spec, [], i + 1, list(self.present))
                            self.record(spec, vals)
                            consumed_next = idx2
                        j = len(chars)
                i = consumed_next if consumed_next is not None else i + 1
                continue
            else:
                self.add_command(tok)
                i += 1
                continue
        self.validate()
        return self

    def gather_single(self, spec, i, present_before):
        if i >= len(self.argv):
            self.err_missing_value(spec)
        tok = self.argv[i]
        if tok == "--":
            self.err_missing_value(spec)
        if tok.startswith("-") and tok != "-":
            cls = self.classify_option_token(tok)
            if cls[0] == "long":
                if cls[1] is None:
                    self.err_unexpected("--" + cls[2], present_before, True, cls[2])
                else:
                    self.err_missing_value(spec)
            else:
                if cls[2] is None:
                    self.err_unexpected("-" + cls[1], present_before, False)
                else:
                    self.err_missing_value(spec)
        return [tok], i + 1

    def gather_multi(self, spec, first_vals, i, present_before):
        vals = list(first_vals)
        while len(vals) < spec.num:
            if i >= len(self.argv):
                if not vals:
                    self.err_missing_value(spec)
                self.err_num_values(spec, len(vals))
            tok = self.argv[i]
            if tok == "--":
                if not vals:
                    self.err_missing_value(spec)
                self.err_num_values(spec, len(vals))
            if spec.allow_hyphen:
                if self.is_known_option_token(tok):
                    if not vals:
                        self.err_missing_value(spec)
                    self.err_num_values(spec, len(vals))
                vals.append(tok)
                i += 1
                continue
            if tok.startswith("-") and tok != "-":
                cls = self.classify_option_token(tok)
                if cls[0] == "long":
                    if cls[1] is None:
                        self.err_unexpected("--" + cls[2], present_before, True, cls[2])
                    else:
                        if not vals:
                            self.err_missing_value(spec)
                        self.err_num_values(spec, len(vals))
                else:
                    if cls[2] is None:
                        self.err_unexpected("-" + cls[1], present_before, False)
                    else:
                        if not vals:
                            self.err_missing_value(spec)
                        self.err_num_values(spec, len(vals))
            vals.append(tok)
            i += 1
        return vals, i

    def add_command(self, tok):
        if tok == "":
            err_write("error: a value is required for '<command>...' but none was supplied\n\nFor more information, try '--help'.\n")
            raise ClapExit(2)
        self.commands.append(tok)
        self.note_present_command()

    def note_present_command(self):
        pass

    def do_help_version(self, key):
        if key == "help":
            out_write(HELP_TEMPLATE.replace("\x00BIN\x00", self.bin))
        else:
            out_write(VERSION + "\n")
        raise ClapExit(0)

    def validate(self):
        # duplicates first
        if self.duplicates:
            key = self.duplicates[0]
            spec = SPEC_BY_KEY[key]
            text = (f"error: the argument '{spec.display}' cannot be used multiple times\n\n"
                    f"{self.full_usage()}\n\nFor more information, try '--help'.\n")
            self.error_exit(text)
        # conflicts: iterate present in order; first arg is earlier one
        for akey in self.present:
            aspec = SPEC_BY_KEY[akey]
            for bkey in aspec.conflicts:
                if bkey in self.present_set:
                    # only report if b appears after a (earlier is a)
                    if self.present.index(akey) < self.present.index(bkey):
                        bspec = SPEC_BY_KEY[bkey]
                        rest = [k for k in self.present if k != bkey]
                        usage = self.smart_usage(rest)
                        text = (f"error: the argument '{aspec.display}' cannot be used with '{bspec.display}'\n\n"
                                f"{usage}\n\nFor more information, try '--help'.\n")
                        self.error_exit(text)
        # required
        missing = []
        # trigger order: order of requiring args in present
        for key in self.present:
            spec = SPEC_BY_KEY[key]
            if spec.requires and spec.requires not in self.present_set:
                if spec.requires not in missing:
                    missing.append(spec.requires)
        cmd_missing = len(self.commands) == 0
        if missing or cmd_missing:
            lines = "error: the following required arguments were not provided:\n"
            for k in missing:
                lines += f"  {SPEC_BY_KEY[k].display}\n"
            if cmd_missing:
                lines += "  <command>...\n"
            usage = self.smart_usage(list(self.present), extra_missing=missing)
            lines += f"\n{usage}\n\nFor more information, try '--help'.\n"
            self.error_exit(lines)


