class ExecResultRec:
    __slots__ = ("real", "user", "system", "memory", "exit_code", "was_signal")

    def __init__(self, real, user, system, memory, exit_code, was_signal):
        self.real = real
        self.user = user
        self.system = system
        self.memory = memory
        self.exit_code = exit_code
        self.was_signal = was_signal


class SpawnFailure(Exception):
    def __init__(self, err):
        self.err = err  # OSError


class SetupFailure(Exception):
    def __init__(self, err):
        self.err = err


_RNG = random.SystemRandom()


def build_child_env(iteration_label):
    env = dict(os.environ)
    env["HYPERFINE_RANDOMIZED_ENVIRONMENT_OFFSET"] = "X" * _RNG.randrange(0, 4096)
    if iteration_label is not None:
        env["HYPERFINE_ITERATION"] = iteration_label
    return env


def execute(argv, env, stdin_source, output_policy):
    """stdin_source: None for /dev/null str, or path str.
       output_policy: ('null',) ('pipe',) ('inherit',) ('file', path)
       Returns ExecResultRec or raises SpawnFailure/SetupFailure(OSError)."""
    # open stdin
    stdin_fd = None
    out_fd = None
    err_fd = None
    pipe_r = None
    pipe_w = None
    opened = []
    try:
        if stdin_source is None:
            stdin_fd = os.open("/dev/null", os.O_RDONLY)
        else:
            stdin_fd = os.open(stdin_source, os.O_RDONLY)
        opened.append(stdin_fd)
        kind = output_policy[0]
        if kind == "null":
            out_fd = os.open("/dev/null", os.O_WRONLY)
            opened.append(out_fd)
            err_fd = os.open("/dev/null", os.O_WRONLY)
            opened.append(err_fd)
        elif kind == "file":
            out_fd = os.open(output_policy[1], os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
            opened.append(out_fd)
            err_fd = os.open("/dev/null", os.O_WRONLY)
            opened.append(err_fd)
        elif kind == "inherit":
            out_fd = 1
            err_fd = 2
        elif kind == "pipe":
            pipe_r, pipe_w = os.pipe()
            out_fd = pipe_w
            err_fd = os.open("/dev/null", os.O_WRONLY)
            opened.append(err_fd)
        else:
            out_fd = os.open("/dev/null", os.O_WRONLY)
            opened.append(out_fd)
            err_fd = out_fd
    except OSError as e:
        for fd in opened:
            try:
                os.close(fd)
            except Exception:
                pass
        raise SetupFailure(e)

    err_r, err_w = os.pipe()  # cloexec by default in py3
    # ensure err_w is cloexec (it is non-inheritable)
    start_ns = time.perf_counter_ns()
    # flush python streams before fork so child doesn't inherit buffers
    try:
        sys.stdout.flush()
    except Exception:
        pass
    try:
        sys.stderr.flush()
    except Exception:
        pass
    pid = os.fork()
    if pid == 0:
        # child
        try:
            try:
                signal.signal(signal.SIGPIPE, signal.SIG_DFL)
            except Exception:
                pass
            os.close(err_r)
            # dup stdin/out/err
            if stdin_fd != 0:
                os.dup2(stdin_fd, 0)
            if out_fd != 1:
                os.dup2(out_fd, 1)
            if err_fd != 2:
                os.dup2(err_fd, 2)
            # close pipe read end if any
            if pipe_r is not None:
                try:
                    os.close(pipe_r)
                except Exception:
                    pass
            os.execvpe(argv[0], argv, env)
        except BaseException as e:
            err_no = getattr(e, "errno", None) or 2
            try:
                os.write(err_w, str(err_no).encode())
            except Exception:
                pass
            os._exit(127)
    # parent
    os.close(err_w)
    if pipe_w is not None:
        try:
            os.close(pipe_w)
        except Exception:
            pass
    # read exec error pipe
    err_data = b""
    while True:
        try:
            chunk = os.read(err_r, 4096)
        except OSError:
            break
        if not chunk:
            break
        err_data += chunk
    os.close(err_r)
    reader_thread = None
    if pipe_r is not None:
        def drain(fd=pipe_r):
            try:
                while True:
                    data = os.read(fd, 65536)
                    if not data:
                        break
            except OSError:
                pass
            try:
                os.close(fd)
            except Exception:
                pass
        reader_thread = threading.Thread(target=drain, daemon=True)
        reader_thread.start()
    # wait
    while True:
        try:
            wpid, status, rusage = os.wait4(pid, 0)
            break
        except InterruptedError:
            continue
    end_ns = time.perf_counter_ns()
    if reader_thread is not None:
        reader_thread.join()
    # close opened parent fds
    for fd in opened:
        try:
            os.close(fd)
        except Exception:
            pass
    if err_data:
        try:
            eno = int(err_data.decode().strip() or "2")
        except Exception:
            eno = 2
        raise SpawnFailure(OSError(eno, os.strerror(eno)))
    real = (end_ns - start_ns) / 1e9
    user = rusage.ru_utime
    system = rusage.ru_stime
    memory = int(rusage.ru_maxrss) * 1024
    if os.WIFEXITED(status):
        code = os.WEXITSTATUS(status)
        return ExecResultRec(real, user, system, memory, code, False)
    if os.WIFSIGNALED(status):
        sig = os.WTERMSIG(status)
        return ExecResultRec(real, user, system, memory, 128 + sig, True)
    return ExecResultRec(real, user, system, memory, 255, False)


# ---------------------------------------------------------------------------
# progress

class Progress:
    SPINNERS = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"

    def __init__(self, enabled, colored):
        self.enabled = enabled
        self.colored = colored
        self.spin_idx = 0
        self.msg = ""
        self.frac = 0.0
        self.eta = 0

    def _draw(self, msg_visible_len, msg_text, frac, eta_secs=0):
        if not self.enabled:
            return
        spinner = self.SPINNERS[self.spin_idx % len(self.SPINNERS)]
        self.spin_idx += 1
        filled = int(frac * 32)
        if filled < 0:
            filled = 0
        if filled > 32:
            filled = 32
        bar = "█" * filled + "░" * (32 - filled)
        pad = 29 - msg_visible_len
        if pad < 0:
            pad = 0
        eta_str = f"{eta_secs // 3600:02d}:{(eta_secs % 3600) // 60:02d}:{eta_secs % 60:02d}"
        frame = f" {spinner} {msg_text}" + " " * pad + "  " + bar + f" ETA {eta_str} " + "\r\x1b[2K"
        err_write(frame)

    def phase(self, msg):
        self.spin_idx = 0
        self._draw(len(msg), msg, 0.0, 0)

    def update(self, msg, frac, eta_secs=0):
        visible = len(msg)
        self._draw(visible, msg, frac, eta_secs)

    def current_estimate(self, mean_secs, unit, frac, eta_secs=0):
        dur = format_duration(mean_secs, unit)
        if self.colored:
            msg_text = f"Current estimate: \x1b[32m{dur}\x1b[0m"
        else:
            msg_text = f"Current estimate: {dur}"
        visible = len(f"Current estimate: {dur}")
        self._draw(visible, msg_text, frac, eta_secs)


