# exporters

class Exporter:
    ORDER = ["export_asciidoc", "export_json", "export_csv", "export_markdown", "export_orgmode"]

    def __init__(self, kind, path):
        self.kind = kind
        self.path = path
        self.fd = None
        if path != "-":
            try:
                self.fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
            except OSError as e:
                raise AppError(f"Could not create export file '{path}': {os_err_str(e)}")


class CSVExportError(Exception):
    pass


def markup_escape(name):
    return name.replace("|", "\\|")


def gen_csv(results):
    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n", quoting=csv.QUOTE_MINIMAL)
    first_params = []
    if results and results[0].parameters:
        first_params = list(results[0].parameters.keys())
    header = ["command", "mean", "stddev", "median", "user", "system", "min", "max"] + [f"parameter_{k}" for k in first_params]
    writer.writerow(header)
    prev_len = len(header)
    for r in results:
        row = [r.command, rust_float_display(r.mean), rust_float_display(r.stddev if r.stddev is not None else 0.0),
               rust_float_display(r.median), rust_float_display(r.user), rust_float_display(r.system),
               rust_float_display(r.min_t), rust_float_display(r.max_t)]
        if r.parameters:
            for k in r.parameters.keys():
                row.append(r.parameters[k])
        if len(row) != prev_len:
            raise CSVExportError(f"CSV error: found record with {len(row)} fields, but the previous record has {prev_len} fields")
        writer.writerow(row)
    return output.getvalue()


def gen_json(results):
    objs = []
    for r in results:
        obj = {}
        obj["command"] = r.command
        obj["mean"] = r.mean
        obj["stddev"] = r.stddev
        obj["median"] = r.median
        obj["user"] = r.user
        obj["system"] = r.system
        obj["min"] = r.min_t
        obj["max"] = r.max_t
        obj["times"] = list(r.times)
        obj["memory_usage_byte"] = list(r.memory)
        obj["exit_codes"] = list(r.exit_codes)
        if r.parameters:
            obj["parameters"] = dict(r.parameters)
        objs.append(obj)
    return json.dumps({"results": objs}, indent=2, ensure_ascii=False) + "\n"


def fastest_of(results):
    best = None
    for r in results:
        if best is None or r.mean < best.mean:
            best = r
    return best


def ordered_for_markup(results, sort_method):
    if sort_method == "mean-time":
        return sorted(results, key=lambda r: r.mean)
    return list(results)


def relative_cell(r, fastest):
    if r is fastest:
        return "1.00"
    ratio, std = relative_speed_and_std(r, fastest)
    if std is None:
        return fmt_fixed(ratio, 2)
    return f"{fmt_fixed(ratio, 2)} ± {fmt_fixed(std, 2)}"


def mean_cell(r, unit):
    if r.stddev is None:
        return duration_number(r.mean, unit)
    return f"{duration_number(r.mean, unit)} ± {duration_number(r.stddev, unit)}"


def gen_markdown(results, sort_method, forced_unit):
    unit = forced_unit or determine_unit(results[0].mean)
    fastest = fastest_of(results)
    rows = ordered_for_markup(results, sort_method)
    label = UNIT_LABEL[unit]
    s = f"| Command | Mean [{label}] | Min [{label}] | Max [{label}] | Relative |\n|:---|---:|---:|---:|---:|\n"
    for r in rows:
        s += f"| `{markup_escape(r.name)}` | {mean_cell(r, unit)} | {duration_number(r.min_t, unit)} | {duration_number(r.max_t, unit)} | {relative_cell(r, fastest)} |\n"
    return s


def gen_asciidoc(results, sort_method, forced_unit):
    unit = forced_unit or determine_unit(results[0].mean)
    fastest = fastest_of(results)
    rows = ordered_for_markup(results, sort_method)
    label = UNIT_LABEL[unit]
    header = (f"[cols=\"<,>,>,>,>\"]\n|===\n| Command \n| Mean [{label}] \n| Min [{label}] \n"
              f"| Max [{label}] \n| Relative \n")
    blocks = []
    for r in rows:
        blocks.append(f"| `{markup_escape(r.name)}` \n| {mean_cell(r, unit)} \n| {duration_number(r.min_t, unit)} \n| {duration_number(r.max_t, unit)} \n| {relative_cell(r, fastest)} \n")
    return header + "\n" + "\n".join(blocks) + "|===\n"


def gen_orgmode(results, sort_method, forced_unit):
    unit = forced_unit or determine_unit(results[0].mean)
    fastest = fastest_of(results)
    rows = ordered_for_markup(results, sort_method)
    label = UNIT_LABEL[unit]
    s = f"| Command  |  Mean [{label}] |  Min [{label}] |  Max [{label}] |  Relative |\n|--+--+--+--+--|\n"
    for r in rows:
        s += f"| ={markup_escape(r.name)}=  |  {mean_cell(r, unit)} |  {duration_number(r.min_t, unit)} |  {duration_number(r.max_t, unit)} |  {relative_cell(r, fastest)} |\n"
    return s


def gen_export(kind, results, sort_method, forced_unit):
    if kind == "export_json":
        return gen_json(results)
    if kind == "export_csv":
        return gen_csv(results)
    if kind == "export_markdown":
        return gen_markdown(results, sort_method, forced_unit)
    if kind == "export_asciidoc":
        return gen_asciidoc(results, sort_method, forced_unit)
    if kind == "export_orgmode":
        return gen_orgmode(results, sort_method, forced_unit)
    return ""


# ---------------------------------------------------------------------------

def main(argv):
    global _COLOR_ENABLED
    parser = Parser(argv)
    try:
        parser.parse()
    except ClapExit as e:
        return e.code
    vals = parser.values
    commands_raw = parser.commands

    style_val = vals.get("style", "auto")
    sort_val = vals.get("sort", "auto")
    time_unit_val = vals.get("time_unit")  # micro/milli/second strings
    forced_unit = None
    if time_unit_val == "microsecond":
        forced_unit = "microsecond"
    elif time_unit_val == "millisecond":
        forced_unit = "millisecond"
    elif time_unit_val == "second":
        forced_unit = "second"

    # resolve output style
    stdout_tty = False
    stderr_tty = False
    try:
        stdout_tty = sys.stdout.isatty()
    except Exception:
        pass
    try:
        stderr_tty = sys.stderr.isatty()
    except Exception:
        pass
    if style_val == "basic":
        color_enabled = False
        interactive = False
        show_main = True
    elif style_val == "none":
        color_enabled = False
        interactive = False
        show_main = False
    elif style_val == "color":
        color_enabled = True
        interactive = False
        show_main = True
    elif style_val == "nocolor":
        color_enabled = False
        interactive = True
        show_main = True
    elif style_val == "full":
        color_enabled = True
        interactive = True
        show_main = True
    else:  # auto
        term = os.environ.get("TERM")
        if "NO_COLOR" in os.environ:
            color_enabled = False
        elif not stdout_tty:
            color_enabled = False
        elif term is None or term in ("dumb", "unknown"):
            color_enabled = False
        else:
            color_enabled = True
        interactive = stdout_tty
        show_main = True
    _COLOR_ENABLED = color_enabled

    def bold(s):
        return f"\x1b[1m{s}\x1b[0m" if color_enabled else s

    def bold_green(s):
        return f"\x1b[1;32m{s}\x1b[0m" if color_enabled else s

    def green(s):
        return f"\x1b[32m{s}\x1b[0m" if color_enabled else s

    def blue(s):
        return f"\x1b[34m{s}\x1b[0m" if color_enabled else s

    def cyan(s):
        return f"\x1b[36m{s}\x1b[0m" if color_enabled else s

    def magenta(s):
        return f"\x1b[35m{s}\x1b[0m" if color_enabled else s

    try:
        # --- numeric arguments (uncolored errors)
        warmup = 0
        if "warmup" in vals:
            warmup = rust_u64_parse(vals["warmup"], "warmup")
        min_runs_opt = None
        if "min_runs" in vals:
            min_runs_opt = rust_u64_parse(vals["min_runs"], "min-runs")
        max_runs_opt = None
        if "max_runs" in vals:
            max_runs_opt = rust_u64_parse(vals["max_runs"], "max-runs")
        exact_runs = None
        if "runs" in vals:
            exact_runs = rust_u64_parse(vals["runs"], "runs")
        if min_runs_opt is not None and max_runs_opt is not None and min_runs_opt > max_runs_opt:
            raise AppError("Conflicting requirements for the number of runs (empty range, min is larger than max)", colored=False)

        # --- output policies (uncolored unknown policy)
        show_output_flag = bool(vals.get("show_output"))
        output_vals = vals.get("output", [])
        output_policies_parsed = []
        for ov in output_vals:
            if ov == "null":
                output_policies_parsed.append(("null",))
            elif ov == "pipe":
                output_policies_parsed.append(("pipe",))
            elif ov == "inherit":
                output_policies_parsed.append(("inherit",))
            elif "/" in ov:
                output_policies_parsed.append(("file", ov))
            else:
                raise AppError(f"Unknown output policy '{ov}'. Use './{ov}' to output to a file named '{ov}'.", colored=False)
        if show_output_flag:
            output_policies_parsed = [("inherit",)]

        # --- shell
        shell_given = vals.get("shell")  # last wins
        no_shell_flag = bool(vals.get("no_shell"))
        shell_tokens = None  # None = no shell
        shell_is_some = True
        if no_shell_flag:
            shell_tokens = None
            shell_is_some = False
        elif shell_given is None or shell_given == "default":
            shell_tokens = ["sh"]
        elif shell_given == "none":
            shell_tokens = None
            shell_is_some = False
        else:
            try:
                toks = shell_parse(shell_given)
            except ShellParseError:
                raise AppError("Failed to parse '--shell <command>' expression as command line: missing closing quote")
            if len(toks) == 0 or toks[0] == "":
                raise AppError("An empty command has been specified for the '--shell <command>' option")
            shell_tokens = toks

        # --- ignore failure
        ignore_mode = None  # None, 'all', or set
        if "ignore_failure" in parser.present_set:
            iv = vals.get("ignore_failure")
            if iv is None or iv == "" or iv == "all-non-zero":
                ignore_mode = "all"
            else:
                codes = set()
                for piece in iv.split(","):
                    codes.add(rust_i32_parse_piece(piece, "ignore-failure"))
                ignore_mode = codes

        def is_ignored(code):
            if ignore_mode == "all":
                return True
            if isinstance(ignore_mode, set):
                return code in ignore_mode
            return False

        # --- input
        input_val = vals.get("input")
        input_source = None  # None = /dev/null, otherwise path
        if input_val is None or input_val == "null":
            input_source = None
        else:
            if not os.path.exists(input_val):
                raise AppError(f"The file '{input_val}' specified as '--input' does not exist")
            input_source = input_val

        # --- parameters
        param_defs = []  # list of (var, [values])
        params_present = False
        scan_values = None
        if "parameter_scan" in parser.present_set:
            params_present = True
            var, min_s, max_s = vals["parameter_scan"]
            step_s = vals.get("parameter_step_size")
            # parse decimals (scan + step)
            try:
                min_d = parse_decimal(min_s)
                max_d = parse_decimal(max_s)
                step_d = parse_decimal(step_s) if step_s is not None else None
            except ValueError as e:
                raise AppError(f"Error while parsing parameter scan arguments (Invalid decimal: {e})")
            if step_d is not None and step_d == 0:
                raise AppError("Zero is not a valid parameter step")
            if step_d is None:
                if not (is_i32_str(min_s) and is_i32_str(max_s)):
                    raise AppError("A step size is required when the range bounds are floating point numbers. The step size can be specified with the '-D/--parameter-step-size <DELTA>' parameter")
                step_d = Decimal(1)
            values_list = []
            cur = min_d
            while cur <= max_d:
                values_list.append(decimal_str(cur))
                if len(values_list) > 100000:
                    raise AppError("Parameter range is too large")
                cur = cur + step_d
            if not values_list:
                raise AppError("Empty parameter range")
            param_defs.append((var, values_list))
        if "parameter_list" in parser.present_set:
            params_present = True
            for var, values_str in vals.get("parameter_list", []):
                param_defs.append((var, values_str.split(",")))
        # duplicate names
        seen_names = set()
        for name, _ in param_defs:
            if name in seen_names:
                raise AppError(f"Duplicate parameter names: {name}")
            seen_names.add(name)

        # combinations: first def varies fastest
        combos = []
        if param_defs:
            value_lists = [v for _, v in param_defs]
            # product over reversed lists
            for prod in itertools.product(*value_lists[::-1]):
                combo_vals = tuple(reversed(prod))
                combos.append(combo_vals)
        else:
            combos = [()]

        # --- build benchmark specs
        class BenchSpec:
            pass

        specs = []
        total_expanded = len(combos) * len(commands_raw)
        names_list = vals.get("command_name", [])
        if params_present:
            if len(names_list) not in (0, 1, total_expanded):
                raise AppError(f"'--command-name' has been specified {len(names_list)} times. It has to appear exactly once, or exactly {total_expanded} times (number of benchmarks)")
        else:
            if len(names_list) > len(commands_raw):
                raise AppError(f"Too many --command-name options: Expected {len(commands_raw)} at most")

        reference_cmd = vals.get("reference")
        reference_name = vals.get("reference_name")
        expanded_index = 0
        if reference_cmd is not None:
            bs = BenchSpec()
            bs.raw_command = reference_cmd
            bs.params = {}
            bs.params_or_none = None
            bs.is_reference = True
            bs.name_template = reference_name
            specs.append(bs)
        for combo in combos:
            params_dict = {}
            if param_defs:
                for (var, _), v in zip(param_defs, combo):
                    params_dict[var] = v
            for ci, raw_cmd in enumerate(commands_raw):
                bs = BenchSpec()
                bs.raw_command = raw_cmd
                bs.params = params_dict
                bs.params_or_none = params_dict if param_defs else None
                bs.is_reference = False
                if params_present:
                    if len(names_list) == 1:
                        bs.name_template = names_list[0]
                    elif len(names_list) == total_expanded and total_expanded > 0:
                        bs.name_template = names_list[expanded_index]
                    else:
                        bs.name_template = None
                else:
                    bs.name_template = names_list[ci] if ci < len(names_list) else None
                specs.append(bs)
                expanded_index += 1

        for bs in specs:
            template = bs.name_template if bs.name_template is not None else bs.raw_command
            base = substitute(template, bs.params) if not bs.is_reference else template
            display = base
            if param_defs and not bs.is_reference:
                missing = [(k, v) for k, v in bs.params.items() if ("{" + k + "}") not in bs.raw_command]
                if missing:
                    display = base + " (" + ", ".join(f"{k} = {v}" for k, v in missing) + ")"
            bs.name_base = base
            bs.display_name = display
            bs.exec_command = substitute(bs.raw_command, bs.params) if not bs.is_reference else bs.raw_command

        # --- exporters (creation)
        exporters = []
        for kind in Exporter.ORDER:
            if kind in parser.present_set:
                path = vals[kind]
                exporters.append(Exporter(kind, path))

        # --- prepare/conclude/output counts
        num_benchmarks_total = len(specs)
        prepares = vals.get("prepare", [])
        concludes = vals.get("conclude", [])
        if len(prepares) not in (0, 1, num_benchmarks_total):
            raise AppError(f"The '--prepare' option has to be provided just once or N times, where N={num_benchmarks_total} is the number of benchmark commands (including a potential reference).")
        if len(concludes) not in (0, 1, num_benchmarks_total):
            raise AppError(f"The '--conclude' option has to be provided just once or N times, where N={num_benchmarks_total} is the number of benchmark commands (including a potential reference).")
        if not show_output_flag and output_vals:
            if len(output_policies_parsed) not in (1, num_benchmarks_total):
                raise AppError(f"The '--output' option has to be provided just once or N times, where N={num_benchmarks_total} is the number of benchmark commands (including a potential reference).")

        setup_cmd = vals.get("setup")
        cleanup_cmd = vals.get("cleanup")

        progress = Progress(interactive and stderr_tty, color_enabled)

        # --- shell calibration
        shell_mean = 0.0
        if shell_tokens is not None:
            progress.phase("Measuring shell spawning time")
            times_cal = []
            for _ in range(50):
                env = build_child_env(None)
                try:
                    rec = execute(shell_tokens + ["-c", ""], env, None, ("null",))
                except (SpawnFailure, SetupFailure):
                    raise AppError(f"Could not measure shell execution time. Make sure you can run '{shell_join(shell_tokens)} -c \"\"'.")
                if rec.exit_code != 0 or rec.was_signal:
                    raise AppError(f"Could not measure shell execution time. Make sure you can run '{shell_join(shell_tokens)} -c \"\"'.")
                times_cal.append(rec.real)
            shell_mean = sum(times_cal) / len(times_cal) if times_cal else 0.0
            progress.phase("Measuring shell spawning time")

        # helper to resolve argv for a command string
        def resolve_argv(cmd_str, for_benchmark, original_cmd_for_msg):
            if shell_tokens is not None:
                return shell_tokens + ["-c", cmd_str]
            # no shell
            try:
                toks = shell_parse(cmd_str)
            except ShellParseError:
                if for_benchmark:
                    raise AppError(f"Failed to parse command '{original_cmd_for_msg}': missing closing quote")
                raise RuntimeError("parse")
            if len(toks) == 0:
                if for_benchmark:
                    raise AppError("Can not execute empty command")
                raise RuntimeError("empty")
            return toks

        def run_aux(cmd_template, bench_params, output_policy, kind_word):
            """kind_word: setup/preparation/conclusion/cleanup for message"""
            cmd_str = substitute(cmd_template, bench_params)
            try:
                argv = resolve_argv(cmd_str, False, cmd_str)
            except Exception:
                raise AppError(f"The {kind_word} command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.")
            env = build_child_env(None)
            try:
                rec = execute(argv, env, input_source, output_policy)
            except Exception:
                raise AppError(f"The {kind_word} command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.")
            if rec.exit_code != 0 or rec.was_signal:
                raise AppError(f"The {kind_word} command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.")
            return rec

        def run_timed_once(bs, iteration_label, output_policy, is_warmup, index):
            """Returns ExecResultRec with status handling; raises AppError on failure."""
            # prepare
            prep_str = bs.prepare_cmd
            if prep_str is not None:
                run_aux(prep_str, bs.params, output_policy, "preparation")
            argv = resolve_argv(bs.exec_command, True, bs.exec_command if not bs.is_reference else bs.raw_command)
            # For -N messages, original command string (with params substituted) is used
            env = build_child_env(iteration_label)
            try:
                rec = execute(argv, env, input_source, output_policy)
            except SpawnFailure as e:
                if shell_tokens is None:
                    raise AppError(f"Failed to run command '{bs.exec_command}': {os_err_str(e.err)}")
                raise AppError(os_err_str(e.err))
            except SetupFailure as e:
                raise AppError(os_err_str(e.err))
            # status check
            failed = rec.was_signal or rec.exit_code != 0
            if failed and not is_ignored(rec.exit_code):
                # conclude not run
                if is_warmup:
                    ctx = "the first warmup run" if index == 0 else f"warmup iteration {index}"
                else:
                    ctx = "the first benchmark run" if index == 0 else f"benchmark iteration {index}"
                if rec.was_signal:
                    raise AppError(f"The process has been terminated by a signal in {ctx}. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.")
                else:
                    raise AppError(f"Command terminated with non-zero exit code {rec.exit_code} in {ctx}. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.")
            # conclude (only if not a non-ignored failure; failures above raised)
            concl_str = bs.conclude_cmd
            if concl_str is not None:
                run_aux(concl_str, bs.params, output_policy, "conclusion")
            return rec

        results = []

        def do_intermediate_export():
            for exp in exporters:
                if exp.path == "-":
                    continue
                content = gen_export_for(exp)
                data = content.encode()
                try:
                    os.lseek(exp.fd, 0, os.SEEK_SET)
                    # write all
                    view = memoryview(data)
                    while view:
                        w = os.write(exp.fd, view)
                        view = view[w:]
                except OSError as e:
                    raise AppError(f"Failed to export results to '{exp.path}': {os_err_str(e)}")

        def gen_export_for(exp):
            try:
                return gen_export(exp.kind, results, sort_val, forced_unit)
            except CSVExportError as e:
                raise AppError(str(e))

        # assign per-spec prepare/conclude/output
        for idx, bs in enumerate(specs):
            if len(prepares) == 1:
                bs.prepare_cmd = prepares[0]
            elif len(prepares) == num_benchmarks_total:
                bs.prepare_cmd = prepares[idx]
            else:
                bs.prepare_cmd = None
            if len(concludes) == 1:
                bs.conclude_cmd = concludes[0]
            elif len(concludes) == num_benchmarks_total:
                bs.conclude_cmd = concludes[idx]
            else:
                bs.conclude_cmd = None
            if output_policies_parsed:
                if len(output_policies_parsed) == 1:
                    bs.output_policy = output_policies_parsed[0]
                else:
                    bs.output_policy = output_policies_parsed[idx]
            else:
                bs.output_policy = ("null",)

        benchmark_number = 0
        for bs in specs:
            benchmark_number += 1
            if show_main:
                if color_enabled:
                    out_write(f"\x1b[1mBenchmark \x1b[0m\x1b[1m{benchmark_number}\x1b[0m: {bs.display_name}\n")
                else:
                    out_write(f"Benchmark {benchmark_number}: {bs.display_name}\n")
            # setup
            if setup_cmd is not None:
                run_aux(setup_cmd, bs.params, bs.output_policy, "setup")
            # warmup
            if warmup and warmup > 0:
                progress.phase("Performing warmup runs")
                for wi in range(warmup):
                    run_timed_once(bs, f"warmup-{wi}", bs.output_policy, True, wi)
                    if warmup > 1:
                        progress.phase("Performing warmup runs")
                        # fraction visual
                        progress.update("Performing warmup runs", (wi + 1) / warmup, 0)
            # timed runs
            result = BenchResult(bs.name_base, bs.display_name, bs.params_or_none, bs.is_reference)
            progress.phase("Initial time measurement")
            total_count = exact_runs  # may be None
            idx_run = 0
            first_raw = None
            while True:
                if total_count is not None and total_count != 0 and idx_run >= total_count:
                    break
                # infinite-loop cases are handled by total_count==0 sentinel below
                rec = run_timed_once(bs, str(idx_run), bs.output_policy, False, idx_run)
                raw = rec.real
                if first_raw is None:
                    first_raw = raw
                    if total_count is None:
                        # estimate
                        if raw == 0:
                            proposed = 10 ** 18
                        else:
                            proposed = int(3.0 / raw)
                        min_eff = min_runs_opt if min_runs_opt is not None else 10
                        cnt = proposed
                        if cnt < min_eff:
                            cnt = min_eff
                        if max_runs_opt is not None and cnt > max_runs_opt:
                            cnt = max_runs_opt
                        total_count = cnt
                corrected = raw - shell_mean if shell_tokens is not None else raw
                if corrected < 0.0:
                    corrected = 0.0
                result.times.append(corrected)
                result.user_times.append(rec.user)
                result.system_times.append(rec.system)
                result.memory.append(rec.memory)
                result.exit_codes.append(rec.exit_code)
                idx_run += 1
                # progress current estimate
                if total_count is not None and total_count != 0 and idx_run < total_count:
                    # mean so far
                    m = sum(result.times) / len(result.times)
                    unit_p = forced_unit or determine_unit(m)
                    remaining = total_count - idx_run
                    # estimate eta based on raw mean
                    raw_mean = (sum(result.times) / len(result.times))
                    eta = int(raw_mean * remaining)
                    progress.current_estimate(m, unit_p, idx_run / total_count if total_count else 0, eta)
                if total_count is not None and total_count == 0:
                    # deliberately continue forever to mimic original behaviour for 0
                    continue
                if total_count is not None and idx_run >= total_count:
                    break
                if total_count is None:
                    break
            result.compute()
            # print result
            unit = forced_unit or determine_unit(result.mean)
            if show_main:
                if len(result.times) == 1:
                    mean_field_plain = format_duration(result.mean, unit)
                    if color_enabled:
                        time_line = (f"  Time (\x1b[1;32mabs\x1b[0m ≡):" + " " * 8 +
                                     f"\x1b[1;32m{mean_field_plain:>8}\x1b[0m" + " " * 15 +
                                     f"[User: \x1b[34m{format_duration(result.user, unit)}\x1b[0m, System: \x1b[34m{format_duration(result.system, unit)}\x1b[0m]\n")
                    else:
                        time_line = (f"  Time (abs ≡):" + " " * 8 +
                                     f"{mean_field_plain:>8}" + " " * 15 +
                                     f"[User: {format_duration(result.user, unit)}, System: {format_duration(result.system, unit)}]\n")
                    out_write(time_line)
                else:
                    mean_s = format_duration(result.mean, unit)
                    std_s = format_duration(result.stddev, unit)
                    min_s = format_duration(result.min_t, unit)
                    max_s = format_duration(result.max_t, unit)
                    if color_enabled:
                        time_line = (f"  Time (\x1b[1;32mmean\x1b[0m ± \x1b[32mσ\x1b[0m):" + " " * 5 +
                                     f"\x1b[1;32m{mean_s:>8}\x1b[0m ± \x1b[32m{std_s:>8}\x1b[0m    "
                                     f"[User: \x1b[34m{format_duration(result.user, unit)}\x1b[0m, System: \x1b[34m{format_duration(result.system, unit)}\x1b[0m]\n")
                        range_line = (f"  Range (\x1b[36mmin\x1b[0m … \x1b[35mmax\x1b[0m):" + " " * 3 +
                                      f"\x1b[36m{min_s:>8}\x1b[0m … \x1b[35m{max_s:>8}\x1b[0m    "
                                      f"\x1b[2m{len(result.times)} runs\x1b[0m\n")
                    else:
                        time_line = (f"  Time (mean ± σ):" + " " * 5 +
                                     f"{mean_s:>8} ± {std_s:>8}    "
                                     f"[User: {format_duration(result.user, unit)}, System: {format_duration(result.system, unit)}]\n")
                        range_line = (f"  Range (min … max):" + " " * 3 +
                                      f"{min_s:>8} … {max_s:>8}    {len(result.times)} runs\n")
                    out_write(time_line)
                    out_write(range_line)
            # warnings
            warnings = []
            if shell_tokens is not None and result.mean < 0.005:
                warnings.append("Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.")
            if any(c != 0 for c in result.exit_codes):
                warnings.append("Ignoring non-zero exit code.")
            # outlier detection
            outlier_kind = None
            if len(result.times) >= 2:
                times = result.times
                med = statistics.median(times)
                absdev = [abs(x - med) for x in times]
                mad = statistics.median(absdev)
                def is_outlier(x):
                    if mad == 0.0:
                        return x != med
                    return abs(0.6745 * (x - med) / mad) > 10.0
                outs = [is_outlier(x) for x in times]
                if outs and outs[0] and times[0] > med:
                    outlier_kind = "first"
                elif any(outs):
                    outlier_kind = "stat"
            if outlier_kind == "first":
                unit_f = determine_unit(result.times[0])
                warnings.append(f"The first benchmarking run for this command was significantly slower than the rest ({format_duration(result.times[0], unit_f)}). This could be caused by (filesystem) caches that were not filled until after the first run. You should consider using the '--warmup' option to fill those caches before the actual benchmark. Alternatively, use the '--prepare' option to clear the caches before each timing run.")
            elif outlier_kind == "stat":
                warnings.append("Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.")
            if warnings:
                warn_word = "\x1b[33mWarning\x1b[0m" if color_enabled else "Warning"
                err_write(" \n" + "".join(f"  {warn_word}: {w}\n" for w in warnings))
            if show_main:
                out_write(" \n")
            # cleanup
            if cleanup_cmd is not None:
                run_aux(cleanup_cmd, bs.params, bs.output_policy, "cleanup")
            results.append(result)
            # intermediate export to files
            do_intermediate_export()

        # summary / note
        if len(results) > 1:
            any_zero = any(r.mean == 0.0 for r in results)
            if any_zero:
                note_word = "\x1b[1;31mNote\x1b[0m" if color_enabled else "Note"
                err_write(f"{note_word}: The benchmark comparison could not be computed as some benchmark times are zero. This could be caused by background interference during the initial calibration phase of hyperfine, in combination with very fast commands (faster than a few milliseconds). Try to re-run the benchmark on a quiet system. If you did not do so already, try the --shell=none/-N option. If it does not help either, you command is most likely too fast to be accurately benchmarked by hyperfine.\n")
            elif show_main:
                # determine denominator
                ref_result = None
                for r in results:
                    if r.is_reference:
                        ref_result = r
                        break
                if sort_val == "command":
                    denom = ref_result if ref_result is not None else fastest_of(results)
                    out_write(bold("Relative speed comparison") + "\n")
                    for r in results:
                        if r is denom:
                            ratio = 1.0
                            rstd = None
                        else:
                            if r.mean >= denom.mean:
                                ratio = fdiv(r.mean, denom.mean) if denom.mean != 0 else math.inf
                            else:
                                ratio = fdiv(denom.mean, r.mean) if r.mean != 0 else math.inf
                            if r.stddev is None or denom.stddev is None:
                                rstd = None
                            else:
                                tr = fdiv(r.stddev, r.mean)
                                td = fdiv(denom.stddev, denom.mean)
                                inside = tr * tr + td * td
                                rstd = ratio * (math.sqrt(inside) if inside >= 0 else math.nan)
                        ratio_str = fmt_fixed(ratio, 2)
                        if color_enabled:
                            line = f"  \x1b[1;32m{ratio_str:>10}\x1b[0m"
                            if rstd is not None:
                                std_str = fmt_fixed(rstd, 2)
                                line += f" ± \x1b[32m{std_str:>5}\x1b[0m  {r.name}\n"
                            else:
                                line += f"          {r.name}\n"
                        else:
                            line = f"  {ratio_str:>10}"
                            if rstd is not None:
                                std_str = fmt_fixed(rstd, 2)
                                line += f" ± {std_str:>5}  {r.name}\n"
                            else:
                                line += f"          {r.name}\n"
                        out_write(line)
                else:
                    subject = ref_result if ref_result is not None else fastest_of(results)
                    out_write(bold("Summary") + "\n")
                    if color_enabled:
                        out_write(f"  \x1b[36m{subject.name}\x1b[0m ran\n")
                    else:
                        out_write(f"  {subject.name} ran\n")
                    others = [r for r in results if r is not subject]
                    others_sorted = sorted(others, key=lambda r: r.mean)
                    for r in others_sorted:
                        if r.mean < subject.mean:
                            ratio = fdiv(subject.mean, r.mean) if r.mean != 0 else math.inf
                            phrase = "slower"
                        else:
                            ratio = fdiv(r.mean, subject.mean) if subject.mean != 0 else math.inf
                            phrase = "faster"
                        if r.stddev is None or subject.stddev is None:
                            rstd = None
                        else:
                            tr = fdiv(r.stddev, r.mean)
                            td = fdiv(subject.stddev, subject.mean)
                            inside = tr * tr + td * td
                            rstd = ratio * (math.sqrt(inside) if inside >= 0 else math.nan)
                        ratio_str = fmt_fixed(ratio, 2)
                        if color_enabled:
                            line = f"\x1b[1;32m{ratio_str:>8}\x1b[0m"
                            if rstd is not None:
                                line += f" ± \x1b[32m{fmt_fixed(rstd, 2)}\x1b[0m"
                            line += f" times {phrase} than \x1b[35m{r.name}\x1b[0m\n"
                        else:
                            line = f"{ratio_str:>8}"
                            if rstd is not None:
                                line += f" ± {fmt_fixed(rstd, 2)}"
                            line += f" times {phrase} than {r.name}\n"
                        out_write(line)
        # final exports
        for exp in exporters:
            content = gen_export_for(exp)
            if exp.path == "-":
                out_write("\n" + content + "\n")
            else:
                data = content.encode()
                try:
                    os.lseek(exp.fd, 0, os.SEEK_SET)
                    view = memoryview(data)
                    while view:
                        w = os.write(exp.fd, view)
                        view = view[w:]
                except OSError as e:
                    raise AppError(f"Failed to export results to '{exp.path}': {os_err_str(e)}")
        # close exporter fds
        for exp in exporters:
            if exp.fd is not None:
                try:
                    os.close(exp.fd)
                except Exception:
                    pass
        return 0
    except AppError as e:
        err_write(app_error_text(e.message, e.colored))
        return 1
    except BrokenPipeError:
        return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
