#!/usr/bin/env python3
import csv
import decimal
from decimal import Decimal
import errno
import io
import itertools
import json
import json.encoder
import math
import os
import random
import re
import signal
import statistics
import sys
import threading
import time

VERSION = "hyperfine 1.20.0"
HELP_TEMPLATE = ""  # filled below

# Ensure ^C behaves like a native program (killed by SIGINT) rather than a
# Python traceback.
try:
    signal.signal(signal.SIGINT, signal.SIG_DFL)
except Exception:
    pass


def _bin_name():
    name = os.path.basename(sys.argv[0]) if sys.argv and sys.argv[0] else "hyperfine"
    return name or "hyperfine"


def out_write(s):
    try:
        sys.stdout.write(s)
        sys.stdout.flush()
    except BrokenPipeError:
        pass


def err_write(s):
    try:
        sys.stderr.write(s)
        sys.stderr.flush()
    except BrokenPipeError:
        pass


_COLOR_ENABLED = False


class AppError(Exception):
    def __init__(self, message, colored=True):
        super().__init__(message)
        self.message = message
        self.colored = colored


def app_error_text(message, colored=True):
    if colored and _COLOR_ENABLED:
        return "\x1b[31mError:\x1b[0m " + message + "\n"
    return "Error: " + message + "\n"


def os_err_str(e):
    err = getattr(e, "errno", None)
    msg = getattr(e, "strerror", None) or str(e)
    if err is not None:
        return f"{msg} (os error {err})"
    return msg


# ---------------------------------------------------------------------------
# shell-words parsing
class ShellParseError(Exception):
    pass


def shell_parse(s):
    tokens = []
    cur = []
    started = False
    state = None  # None, "'", '"'
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if state == "'":
            if c == "'":
                state = None
            else:
                cur.append(c)
            i += 1
            continue
        if state == '"':
            if c == '"':
                state = None
                i += 1
                continue
            if c == "\\" and i + 1 < n and s[i + 1] in ('$', '`', '"', "\\", "\n"):
                if s[i + 1] != "\n":
                    cur.append(s[i + 1])
                i += 2
                continue
            cur.append(c)
            i += 1
            continue
        # unquoted
        if c.isspace():
            if started:
                tokens.append("".join(cur))
                cur = []
                started = False
            i += 1
            continue
        if c == "'":
            state = "'"
            started = True
            i += 1
            continue
        if c == '"':
            state = '"'
            started = True
            i += 1
            continue
        if c == "\\":
            started = True
            if i + 1 < n:
                cur.append(s[i + 1])
                i += 2
            else:
                cur.append("\\")
                i += 1
            continue
        cur.append(c)
        started = True
        i += 1
    if state is not None:
        raise ShellParseError("missing closing quote")
    if started:
        tokens.append("".join(cur))
    return tokens


def shell_join(tokens):
    parts = []
    for tok in tokens:
        if tok == "" or any(ch.isspace() or ch in ("'", '"') for ch in tok):
            parts.append("'" + tok.replace("'", "'\\''") + "'")
        else:
            parts.append(tok)
    return " ".join(parts)


# ---------------------------------------------------------------------------
# numeric parsing (Rust integer parse error messages)
def rust_u64_parse(s, opt_long):
    # returns int or raises AppError (uncolored)
    if s == "":
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': cannot parse integer from empty string",
            colored=False,
        )
    body = s
    neg = False
    if body.startswith("+"):
        body = body[1:]
        if body == "":
            raise AppError(
                f"Could not read numeric integer argument to '--{opt_long}': invalid digit found in string",
                colored=False,
            )
    if body.startswith("-"):
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': invalid digit found in string",
            colored=False,
        )
    value = 0
    overflow = False
    for ch in body:
        if not ("0" <= ch <= "9"):
            if overflow:
                break
            raise AppError(
                f"Could not read numeric integer argument to '--{opt_long}': invalid digit found in string",
                colored=False,
            )
        if not overflow:
            value = value * 10 + (ord(ch) - 48)
            if value > 18446744073709551615:
                overflow = True
    if overflow:
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': number too large to fit in target type",
            colored=False,
        )
    return value


def rust_i32_parse_piece(s, opt_long):
    if s == "":
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': cannot parse integer from empty string"
        )
    t = s
    sign = 1
    if t.startswith("+"):
        t = t[1:]
    elif t.startswith("-"):
        sign = -1
        t = t[1:]
    if t == "" or any(not ("0" <= ch <= "9") for ch in t):
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': invalid digit found in string"
        )
    val = sign * int(t)
    if val > 2147483647:
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': number too large to fit in target type"
        )
    if val < -2147483648:
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': number too small to fit in target type"
        )
    return val


DECIMAL_MAX = Decimal("79228162514264337593543950335")


def parse_decimal(s):
    """Return Decimal or raise ValueError with kind string."""
    if s == "":
        raise ValueError("empty")
    body = s
    if body[0] in "+-":
        body = body[1:]
    # character check
    for ch in body:
        if not (("0" <= ch <= "9") or ch in "._"):
            raise ValueError("unknown character")
    if body.count(".") > 1:
        raise ValueError("two decimal points")
    if not any("0" <= ch <= "9" for ch in body):
        raise ValueError("no digits found")
    clean = s.replace("_", "")
    try:
        val = Decimal(clean)
    except Exception:
        raise ValueError("unknown character")
    if abs(val) > DECIMAL_MAX:
        raise ValueError("overflow from too many digits")
    return val


def decimal_str(d):
    return format(d, "f")


def is_i32_str(s):
    if not s:
        return False
    t = s
    if t[0] in "+-":
        t = t[1:]
    if not t or any(not ("0" <= ch <= "9") for ch in t):
        return False
    v = int(s)
    return -2147483648 <= v <= 2147483647


# ---------------------------------------------------------------------------
# formatting

def fmt_fixed(x, decimals):
    if isinstance(x, float):
        if math.isnan(x):
            return "NaN"
        if math.isinf(x):
            return "inf" if x > 0 else "-inf"
    return f"{x:.{decimals}f}"


def determine_unit(seconds):
    # returns 'second'/'millisecond'/'microsecond'
    if seconds >= 1.0:
        return "second"
    if seconds >= 0.001:
        return "millisecond"
    return "microsecond"


UNIT_LABEL = {"second": "s", "millisecond": "ms", "microsecond": "µs"}


def duration_number(seconds, unit):
    if unit == "second":
        return fmt_fixed(seconds, 3)
    if unit == "millisecond":
        return fmt_fixed(seconds * 1000.0, 1)
    return fmt_fixed(seconds * 1000000.0, 1)


def format_duration(seconds, unit):
    return f"{duration_number(seconds, unit)} {UNIT_LABEL[unit]}"


def fdiv(a, b):
    if b == 0.0:
        if a == 0.0 or (isinstance(a, float) and math.isnan(a)):
            return math.nan
        # sign of inf: a/b where b is +0.0 in our uses
        return math.inf if a > 0 else -math.inf
    return a / b


def relative_speed_and_std(result, fastest):
    """returns (ratio, ratio_std or None)"""
    if fastest.mean == 0.0:
        ratio = math.inf
    else:
        ratio = result.mean / fastest.mean
    if result.stddev is None or fastest.stddev is None:
        return ratio, None
    # mimic float arithmetic
    term_r = fdiv(result.stddev, result.mean)
    term_f = fdiv(fastest.stddev, fastest.mean)
    inside = term_r * term_r + term_f * term_f
    std = ratio * (math.sqrt(inside) if inside >= 0 else math.nan)
    return ratio, std


def rust_float_display(x):
    """Rust {} for f64: plain decimal, no exponent, integral values without .0"""
    if isinstance(x, float):
        if math.isnan(x):
            return "NaN"
        if math.isinf(x):
            return "inf" if x > 0 else "-inf"
    if x == 0:
        # handle -0.0: Rust prints -0 ? str(-0.0) in Rust is "-0"
        if isinstance(x, float) and math.copysign(1.0, x) < 0:
            return "-0"
        return "0"
    s = format(Decimal(repr(x)), "f")
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


def rust_json_float(x):
    if isinstance(x, float):
        if math.isnan(x):
            return "NaN"
        if math.isinf(x):
            return "Infinity" if x > 0 else "-Infinity"
    s = repr(x)
    if "e" in s or "E" in s:
        mant, exp = s.replace("E", "e").split("e")
        exp_int = int(exp)
        s = f"{mant}e{exp_int}"
    return s


json.encoder.FLOAT_REPR = rust_json_float


