class Spec:
    def __init__(self, key, short, long_, display, kind="set", num=1, values=None,
                 conflicts=(), requires=None, allow_hyphen=False):
        self.key = key
        self.short = short
        self.long = long_
        self.display = display
        self.kind = kind  # set, append, flag, optflag
        self.num = num
        self.values = values
        self.conflicts = list(conflicts)
        self.requires = requires
        self.allow_hyphen = allow_hyphen


SPECS = []
_spec_by_long = {}
_spec_by_short = {}


def _add(spec):
    SPECS.append(spec)
    if spec.long:
        _spec_by_long[spec.long] = spec
    if spec.short:
        _spec_by_short[spec.short] = spec
    return spec


