                    cur.append(s[i + 1])
                i += 2
                continue
            cur.append(c)
            i += 1
            continue
        # unquoted
        if c.isspace():
            if started:
                tokens.append("".join(cur))
                cur = []
                started = False
            i += 1
            continue
        if c == "'":
            state = "'"
            started = True
            i += 1
            continue
        if c == '"':
            state = '"'
            started = True
            i += 1
