    if t.startswith("+"):
        t = t[1:]
    elif t.startswith("-"):
        sign = -1
        t = t[1:]
    if t == "" or any(not ("0" <= ch <= "9") for ch in t):
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': invalid digit found in string"
        )
    val = sign * int(t)
    if val > 2147483647:
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': number too large to fit in target type"
        )
    if val < -2147483648:
        raise AppError(
            f"Could not read numeric integer argument to '--{opt_long}': number too small to fit in target type"
        )
    return val


DECIMAL_MAX = Decimal("79228162514264337593543950335")


def parse_decimal(s):
    """Return Decimal or raise ValueError with kind string."""
    if s == "":
        raise ValueError("empty")
    body = s
    if body[0] in "+-":
        body = body[1:]
    # character check
    for ch in body:
        if not (("0" <= ch <= "9") or ch in "._"):
            raise ValueError("unknown character")
    if body.count(".") > 1:
        raise ValueError("two decimal points")
    if not any("0" <= ch <= "9" for ch in body):
        raise ValueError("no digits found")
    clean = s.replace("_", "")
    try:
        val = Decimal(clean)
    except Exception:
        raise ValueError("unknown character")
    if abs(val) > DECIMAL_MAX:
        raise ValueError("overflow from too many digits")
    return val


def decimal_str(d):
    return format(d, "f")


def is_i32_str(s):
    if not s:
        return False
    t = s
    if t[0] in "+-":
        t = t[1:]
    if not t or any(not ("0" <= ch <= "9") for ch in t):
        return False
    v = int(s)
    return -2147483648 <= v <= 2147483647


# ---------------------------------------------------------------------------
# formatting

def fmt_fixed(x, decimals):
    if isinstance(x, float):
        if math.isnan(x):
            return "NaN"
        if math.isinf(x):
            return "inf" if x > 0 else "-inf"
    return f"{x:.{decimals}f}"


def determine_unit(seconds):
    # returns 'second'/'millisecond'/'microsecond'
    if seconds >= 1.0:
        return "second"
    if seconds >= 0.001:
        return "millisecond"
    return "microsecond"


UNIT_LABEL = {"second": "s", "millisecond": "ms", "microsecond": "µs"}


def duration_number(seconds, unit):
    if unit == "second":
        return fmt_fixed(seconds, 3)
    if unit == "millisecond":
        return fmt_fixed(seconds * 1000.0, 1)
    return fmt_fixed(seconds * 1000000.0, 1)


def format_duration(seconds, unit):
    return f"{duration_number(seconds, unit)} {UNIT_LABEL[unit]}"


def fdiv(a, b):
    if b == 0.0:
        if a == 0.0 or (isinstance(a, float) and math.isnan(a)):
            return math.nan
        # sign of inf: a/b where b is +0.0 in our uses
        return math.inf if a > 0 else -math.inf
    return a / b


def relative_speed_and_std(result, fastest):
    """returns (ratio, ratio_std or None)"""
    if fastest.mean == 0.0:
        ratio = math.inf
    else:
        ratio = result.mean / fastest.mean
    if result.stddev is None or fastest.stddev is None:
        return ratio, None
    # mimic float arithmetic
    term_r = fdiv(result.stddev, result.mean)
    term_f = fdiv(fastest.stddev, fastest.mean)
    inside = term_r * term_r + term_f * term_f
    std = ratio * (math.sqrt(inside) if inside >= 0 else math.nan)
    return ratio, std


def rust_float_display(x):
    """Rust {} for f64: plain decimal, no exponent, integral values without .0"""
    if isinstance(x, float):
        if math.isnan(x):
            return "NaN"
        if math.isinf(x):
            return "inf" if x > 0 else "-inf"
    if x == 0:
        # handle -0.0: Rust prints -0 ? str(-0.0) in Rust is "-0"
        if isinstance(x, float) and math.copysign(1.0, x) < 0:
            return "-0"
        return "0"
    s = format(Decimal(repr(x)), "f")
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


def rust_json_float(x):
    if isinstance(x, float):
        if math.isnan(x):
            return "NaN"
        if math.isinf(x):
            return "Infinity" if x > 0 else "-Infinity"
    s = repr(x)
    if "e" in s or "E" in s:
        mant, exp = s.replace("E", "e").split("e")
        exp_int = int(exp)
        s = f"{mant}e{exp_int}"
    return s


json.encoder.FLOAT_REPR = rust_json_float


