class BenchResult:
    def __init__(self, name_base, display_name, params, is_reference=False):
        self.command = name_base  # for json/csv
        self.name = display_name
        self.parameters = params  # dict or None
        self.is_reference = is_reference
        self.times = []
        self.user_times = []
        self.system_times = []
        self.memory = []
        self.exit_codes = []
        self.mean = 0.0
        self.stddev = None
        self.median = 0.0
        self.user = 0.0
        self.system = 0.0
        self.min_t = 0.0
        self.max_t = 0.0

    def compute(self):
        n = len(self.times)
        self.mean = sum(self.times) / n if n else 0.0
        self.median = statistics.median(self.times) if n else 0.0
        if n > 1:
            # sample stddev
            m = self.mean
            var = sum((x - m) ** 2 for x in self.times) / (n - 1)
            self.stddev = math.sqrt(var)
        else:
            self.stddev = None
        self.user = sum(self.user_times) / n if n else 0.0
        self.system = sum(self.system_times) / n if n else 0.0
        self.min_t = min(self.times) if n else 0.0
        self.max_t = max(self.times) if n else 0.0


def substitute(text, params):
    if not params:
        return text
    out = text
    for k, v in params.items():
        out = out.replace("{" + k + "}", v)
    return out


